#!/usr/bin/env python3
"""Discard Hold'em bot -- low-risk, value-oriented, range-aware.

Pipeline: table-driven preflop -> Monte-Carlo flop equity (incl. discard) ->
opponent-range inference from the exposed discard and betting -> equity-vs-pot-odds
decisions, with a small set of position- and context-dependent bluffs.  All debug goes to
stderr; stdout carries protocol JSON only.
"""
import sys
import json
import math
import random
import time
from itertools import combinations, permutations
from time import perf_counter

RANKS = "23456789TJQKA"
SUITS = "shdc"
CID = {}
CSTR = []
for _r in range(13):
    for _s in range(4):
        CID[RANKS[_r] + SUITS[_s]] = _r * 4 + _s
        CSTR.append(RANKS[_r] + SUITS[_s])

M32 = (1 << 32) - 1
P5 = [5 ** i for i in range(13)]
W = [P5[c >> 2] + (1 << (32 + 3 * (c & 3))) for c in range(52)]

# flush table: suit-count word (4 x 3 bits) -> suit with >=5 cards, else -1
FL = [-1] * 4096
for _s in range(4096):
    for _k in range(4):
        if ((_s >> (3 * _k)) & 7) >= 5:
            FL[_s] = _k

# straight table over 13-bit rank masks -> high card index of best straight, else -1
STH = [-1] * 8192
for _m in range(8192):
    for _h in range(12, 3, -1):
        _need = 31 << (_h - 4)
        if _m & _need == _need:
            STH[_m] = _h
            break
    else:
        if _m & 4111 == 4111:
            STH[_m] = 3

DESC = list(range(12, -1, -1))


def _score(cnt):
    quads = []
    trips = []
    pairs = []
    mask = 0
    for r in DESC:
        c = cnt[r]
        if c:
            mask |= 1 << r
            if c == 4:
                quads.append(r)
            elif c == 3:
                trips.append(r)
            elif c == 2:
                pairs.append(r)
    if quads:
        q = quads[0]
        rest = [r for r in DESC if cnt[r] and r != q]
        return (7 << 20) | (q << 16) | (rest[0] << 12)
    if trips and (len(trips) > 1 or pairs):
        t = trips[0]
        p = max(trips[1:] + pairs)
        return (6 << 20) | (t << 16) | (p << 12)
    h = STH[mask]
    if h >= 0:
        return (4 << 20) | (h << 16)
    if trips:
        t = trips[0]
        ks = [r for r in DESC if cnt[r] and r != t][:2]
        return (3 << 20) | (t << 16) | (ks[0] << 12) | (ks[1] << 8)
    if len(pairs) >= 2:
        p1, p2 = pairs[0], pairs[1]
        k = max(r for r in range(13) if cnt[r] and r != p1 and r != p2)
        return (2 << 20) | (p1 << 16) | (p2 << 12) | (k << 8)
    if pairs:
        p = pairs[0]
        ks = [r for r in DESC if cnt[r] and r != p][:3]
        return (1 << 20) | (p << 16) | (ks[0] << 12) | (ks[1] << 8) | (ks[2] << 4)
    ks = [r for r in DESC if cnt[r]][:5]
    return (ks[0] << 16) | (ks[1] << 12) | (ks[2] << 8) | (ks[3] << 4) | ks[4]


NF = {}


def _build_nf():
    cnt = [0] * 13

    def rec(r, n, key):
        if r == 13:
            if n >= 5:
                NF[key] = _score(cnt)
            return
        for c in range(5):
            if n + c > 7:
                break
            cnt[r] = c
            rec(r + 1, n + c, key + c * P5[r])
        cnt[r] = 0

    rec(0, 0, 0)


_build_nf()


def _flush_score(cards, suit):
    rs = sorted([c >> 2 for c in cards if (c & 3) == suit], reverse=True)
    mask = 0
    for r in rs:
        mask |= 1 << r
    h = STH[mask]
    if h >= 0:
        return (8 << 20) | (h << 16)
    return ((5 << 20) | (rs[0] << 16) | (rs[1] << 12) | (rs[2] << 8) | (rs[3] << 4) | rs[4])


def ev(cards):
    """Best-hand score (higher wins) for 5-7 cards (card = rank*4+suit)."""
    t = 0
    for c in cards:
        t += W[c]
    s = NF[t & M32]
    f = FL[t >> 32]
    if f >= 0:
        fs = _flush_score(cards, f)
        if fs > s:
            s = fs
    return s


def ev_sum(t, cards):
    s = NF[t & M32]
    f = FL[t >> 32]
    if f >= 0:
        fs = _flush_score(cards, f)
        if fs > s:
            s = fs
    return s


# ---------------------------------------------------------------- heuristics

def straight_outs(mask):
    n = 0
    for r in range(13):
        if not (mask >> r) & 1 and STH[mask | (1 << r)] >= 0:
            n += 1
    return n


def flop_value(h1, h2, b3):
    """Heuristic flop strength of keeping (h1,h2) -- used to model discards."""
    cards = [h1, h2] + b3
    s = ev(cards)
    cat = s >> 20
    r1 = (s >> 16) & 15
    r2 = (s >> 12) & 15
    hr1 = h1 >> 2
    hr2 = h2 >> 2
    if cat == 1 and hr1 != r1 and hr2 != r1:
        v = max(hr1, hr2) + 0.4 + 0.02 * min(hr1, hr2)
    else:
        v = cat * 14.0 + r1 + 0.35 * r2 / 12.0
    if cat < 5:
        # flush draw
        sc = [0, 0, 0, 0]
        for c in cards:
            sc[c & 3] += 1
        for su in range(4):
            if sc[su] == 4 and ((h1 & 3) == su or (h2 & 3) == su):
                v += 6.0
                break
        if cat < 4:
            mask = 0
            bmask = 0
            for c in b3:
                bmask |= 1 << (c >> 2)
            mask = bmask | (1 << hr1) | (1 << hr2)
            oa = straight_outs(mask)
            ob = straight_outs(bmask)
            if oa > ob:
                v += 5.0 if oa >= 2 else 2.5
    return v


PERMS = list(permutations(range(4)))


def canon(cards):
    best = None
    for p in PERMS:
        t = tuple(sorted((-(c >> 2), p[c & 3]) for c in cards))
        if best is None or t < best:
            best = t
    return "".join(RANKS[-r] + str(s) for r, s in best)


def logit(p):
    p = min(0.995, max(0.005, p))
    return math.log(p / (1.0 - p))


def sigm(x):
    return 1.0 / (1.0 + math.exp(-x))


