def heur_pre(cards):
    rs = sorted((c >> 2 for c in cards), reverse=True)
    e = 0.34 + 0.016 * (rs[0] + rs[1]) + 0.004 * rs[2]
    if rs[0] == rs[1] or rs[1] == rs[2]:
        e += 0.06
    su = [c & 3 for c in cards]
    if len(set(su)) == 1:
        e += 0.03
    elif len(set(su)) == 2:
        e += 0.012
    return min(0.8, e)


def range_eq(q):
    if not RANGE_EQ:
        return 0.5 + 0.2 * (1 - q)
    i = int(round(q * 100))
    i = max(0, min(len(RANGE_EQ) - 1, i))
    return RANGE_EQ[i]


