def mult(kind, k, pct, b, q=0.35):
    """Weight of a hand at percentile `pct` (0 weakest .. 1 strongest) given an opponent event."""
    if pct < 0.0:
        pct = 0.0
    elif pct > 1.0:
        pct = 1.0
    if kind == 'bet' or kind == 'rse':
        bb = b if b < 0.9 * q else 0.9 * q
        v = (q - bb) / (1.0 - bb)
        v = v * k
        if v > 1.0:
            v = 1.0
        elif v < 0.03:
            v = 0.03
        x = (pct - (1.0 - v)) / 0.07
        if x > 30.0:
            sg = 1.0
        elif x < -30.0:
            sg = 0.0
        else:
            sg = 1.0 / (1.0 + math.exp(-x))
        return bb + (1.0 - bb) * sg
    if kind == 'agg':
        return b + (1.0 - b) * (pct ** k)
    if kind == 'check':
        return 0.5 + 0.5 * ((1.0 - pct) ** 0.7)
    if kind == 'call':
        return 0.35 + 0.65 * (pct ** 0.6)
    if kind == 'pre':
        return 0.25 + 0.75 * (pct ** k)
    return 1.0


def opp_events(hist, me_button):
    """Opponent events [(street, kind, k, f)] reconstructed from a history list."""
    ev_out = []
    prev = [0, 0]
    bets = [0, 0]
    cur = None
    pre_raises = 0
    first_in_street = True
    for e in hist:
        s = e['street']
        if s != cur:
            first_in_street = True
            if cur is not None:
                prev = [prev[0] + bets[0], prev[1] + bets[1]]
            cur = s
            if s == 'preflop':
                bets = [1, 2] if me_button else [2, 1]
            else:
                bets = [0, 0]
        a = e['action']
        actor = 0 if e['actor'] == 'me' else 1
        other = 1 - actor
        pot_before = prev[0] + prev[1] + bets[0] + bets[1]
        to_call = bets[other] - bets[actor]
        if a == 'raise':
            amt = e['amount']
            f = (amt - bets[other]) / float(max(pot_before + to_call, 1))
            allin = prev[actor] + amt >= 200
            if actor == 1:
                if s == 'preflop':
                    k = 0.5 if pre_raises == 0 else (1.0 if pre_raises == 1 else 1.6)
                    ev_out.append((s, 'pre', k, f, 0))
                else:
                    sc = 1.0
                    if f > 1.2:
                        sc = 0.6
                    if allin:
                        sc = 0.5
                    ev_out.append((s, 'rse' if bets[other] > 0 else 'bet', sc, f, 1 if first_in_street else 2))
            if s == 'preflop':
                pre_raises += 1
            bets[actor] = amt
        elif a == 'call':
            if actor == 1 and s != 'preflop':
                ev_out.append((s, 'call', 0, 0, 0))
            bets[actor] = e.get('amount', bets[other])
        elif a == 'check':
            if actor == 1 and s != 'preflop':
                ev_out.append((s, 'check', 0, 0, 0))
        first_in_street = False
    return ev_out



PRIOR_POL = (0.45, 0.35, 0.20)   # equity-based, lowest-card, random


def disc_probs(a, b, d, b3, T=1.0, va=None):
    """P(discard d | original hand {a,b,d}) under each policy [equity, lowest, random]."""
    vab = flop_value(a, b, b3)
    vad = flop_value(a, d, b3) if va is None else va[0]
    vbd = flop_value(b, d, b3) if va is None else va[1]
    best = max(vab, vad, vbd)
    e1 = math.exp((vab - best) / T)
    z = e1 + math.exp((vad - best) / T) + math.exp((vbd - best) / T)
    p_eq = e1 / z
    ra, rb, rd = a >> 2, b >> 2, d >> 2
    mn = min(ra, rb, rd)
    if rd == mn:
        ties = (ra == mn) + (rb == mn) + 1
        p_low = 1.0 / ties
    else:
        p_low = 0.03
    return (p_eq, p_low, 1.0 / 3.0)

# -------------------------------------------------------------- opp range

class Range:
    def __init__(self, ag, my2, my_disc, opp_disc, b3):
        dead = set(my2) | {my_disc, opp_disc} | set(b3)
        self.unseen = [c for c in range(52) if c not in dead]
        d = opp_disc
        post = ag.policy_post()
        self.b3 = b3
        vd = {}
        for a in self.unseen:
            vd[a] = flop_value(a, d, b3)
        self.combos = []
        self.wd = []
        self.sflop = []
        rd = d >> 2
        for a, b in combinations(self.unseen, 2):
            vab = flop_value(a, b, b3)
            vad = vd[a]
            vbd = vd[b]
            best = max(vab, vad, vbd)
            e1 = math.exp(vab - best)
            z = e1 + math.exp(vad - best) + math.exp(vbd - best)
            p_eq = e1 / z
            ra = a >> 2
            rb = b >> 2
            mn = min(ra, rb, rd)
            if rd == mn:
                p_low = 1.0 / ((ra == mn) + (rb == mn) + 1)
            else:
                p_low = 0.03
            self.combos.append((a, b))
            self.wd.append(post[0] * p_eq + post[1] * p_low + post[2] * (1.0 / 3.0))
            self.sflop.append(best)
        self.pcts = {}
        self.scores = {}

    def strengths(self, street, board):
        if street in ('preflop', 'flop'):
            return self.sflop
        key = street
        if key not in self.scores:
            bs = set(board)
            self.scores[key] = [(-1 if (a in bs or b in bs) else ev([a, b] + board))
                                for a, b in self.combos]
        return self.scores[key]

    def pct(self, street, board):
        key = 'flop' if street in ('preflop', 'flop') else street
        if key in self.pcts:
            return self.pcts[key]
        st = self.strengths(street, board)
        n = len(st)
        wd = [(0.0 if st[i] < 0 else self.wd[i]) for i in range(n)]
        order = sorted(range(n), key=st.__getitem__)
        tot = sum(wd) or 1.0
        out = [0.5] * n
        cum = 0.0
        i = 0
        while i < n:
            j = i
            gw = 0.0
            while j < n and st[order[j]] == st[order[i]]:
                gw += wd[order[j]]
                j += 1
            p = (cum + 0.5 * gw) / tot
            for t in range(i, j):
                out[order[t]] = p
            cum += gw
            i = j
        self.pcts[key] = out
        return out

    def pct_of(self, street, board, score):
        st = self.strengths(street, board)
        tot = 0.0
        below = 0.0
        for i, s in enumerate(st):
            if s < 0:
                continue
            w = self.wd[i]
            tot += w
            if s < score:
                below += w
            elif s == score:
                below += 0.5 * w
        return below / (tot or 1.0)


_ERRS = [0]


def elog(msg):
    if _ERRS[0] < 40:
        _ERRS[0] += 1
        try:
            print(msg, file=sys.stderr)
        except Exception:
            pass


# ------------------------------------------------------------------ agent

class Agent:
    def __init__(self, seed=None):
        self.rng = random.Random(seed)
        self.total_hands = 200
        self.time_left = 30000.0
        self.h = {}
        self.seat = 'button'
        self.fast = False
        self.scale = 1.0
        self.ema_ms = 0.0
        self.prev_left = None
        self.prev_hid = None
        self.last_tl = None        # bank at the previous request: the drop since then is what our last reply cost
        self.min_rep = None        # cheapest reply cost seen so far (lower bound on a safe-mode reply)
        self.n_rep = 0
        self.n_hands = 0
        self.st = {'agg_n': 0, 'agg_weak': 0, 'open_n': 0, 'open_r': 0,
                   'b3_n': 0, 'b3_r': 0, 'disc_n': 0, 'disc_m': 0,
                   'dec_n': 0, 'dec_agg': 0,
                   'ob_n': 0, 'ob_fold': 0, 'vb_n': 0, 'vb_call': 0,
                   'pol_ll': [0.0, 0.0, 0.0], 'iso_n': 0, 'iso_r': 0,
                   'o_n': 0, 'o_b': 0, 'f_n': 0, 'f_r': 0,
                   'bs': [0, 0, 0, 0], 'cal_n': 0, 'cal_d': 0.0,
                   'oc': {}}
        self.done = False

    # ------------------------------------------------------------ stats
    def bluff(self):
        s = self.st
        weak = (s['agg_weak'] + 0.9) / (s['agg_n'] + 8.0)
        return min(0.8, max(0.05, 1.2 * weak))

    def bluff_q(self, q):
        s = self.st
        weak = (s['agg_weak'] + 0.9) / (s['agg_n'] + 8.0)
        return min(0.9, max(0.03, weak * q / 0.4))

    def q_bet(self, ctx=0, street='flop'):
        s = self.st
        base = (s['o_b'] + 0.35 * 8) / (s['o_n'] + 8.0)
        if ctx and self.CTX_Q:
            n = b = 0
            for k, v in s['oc'].items():
                if k[0] == ctx:
                    n += v[0]
                    b += v[1]
            base = (b + 6 * base) / (n + 6.0)
            v = s['oc'].get((ctx, street))
            if v:
                base = (v[1] + 6 * base) / (v[0] + 6.0)
        return min(1.0, max(0.12, base))

    def sz_tail(self, f):
        """Share of the opponent's bets that are at least as large as this one (size-aware range)."""
        if not self.SZ_AWARE:
            return 1.0
        b = 0 if f < 0.4 else (1 if f < 0.7 else (2 if f < 1.05 else 3))
        bs = self.st['bs']
        pr = self.SZ_PRIOR
        return (sum(bs[b:]) + sum(pr[b:])) / (sum(bs) + sum(pr))

    def river_adj(self):
        """Self-calibration: how our river bluff-catches against this opponent actually did, vs predicted."""
        s = self.st
        dev = (s['cal_d'] + self.RCAL_PRIOR * self.RCAL_N0) / (s['cal_n'] + self.RCAL_N0)
        a = -self.RCAL_SLOPE * (dev - self.RCAL_PRIOR)
        return max(-self.RCAL_MAX, min(self.RCAL_MAX, a))

    def bet_this_street(self, req):
        for e in req['history']:
            if e['street'] == req['street'] and e['actor'] == 'me' and e['action'] == 'raise':
                return True
        return False

    def face_add(self, si):
        fa = self.FACE_ADD[si]
        if self.CALIB:
            s = self.st
            dev = (s['cal_d'] + self.CAL_PRIOR * self.CAL_N0) / (s['cal_n'] + self.CAL_N0)
            fa += self.CALIB * (self.CAL_PRIOR - dev) * self.CAL_W[si]
            if fa < 0.0:
                fa = 0.0
        return fa

    def q_rse(self):
        s = self.st
        return min(0.9, max(0.05, (s['f_r'] + 0.12 * 10) / (s['f_n'] + 10.0)))

    def mult(self, kind, k, pct, b, q=0.35):
        if (kind == 'check' or kind == 'call') and not self.EVT_MILD:
            return 1.0
        if kind == 'pre' and not self.PRE_EVT:
            return 1.0
        return mult(kind, k, pct, b, q)

    def policy_post(self):
        ll = self.st['pol_ll']
        m = max(ll[i] + math.log(PRIOR_POL[i]) for i in range(3))
        w = [math.exp(ll[i] + math.log(PRIOR_POL[i]) - m) for i in range(3)]
        t = sum(w)
        return [x / t for x in w]

    def steal_s(self):
        st = self.st
        if st['ob_n'] < 8:
            return 0.0
        fr = (st['ob_fold'] + 0.4 * 6) / (st['ob_n'] + 6.0)
        return min(1.0, max(0.0, (fr - 0.45) / 0.35))

    def call_rate(self):
        st = self.st
        if st['vb_n'] < 10:
            return 0.55
        return (st['vb_call'] + 0.55 * 6) / (st['vb_n'] + 6.0)

    def q_open(self):
        s = self.st
        return min(1.0, max(0.2, (s['open_r'] + 0.55 * 8) / (s['open_n'] + 8.0)))

    def q_iso(self):
        """How often the opponent raises from the big blind after our button limp."""
        s = self.st
        return min(1.0, max(0.06, (s['iso_r'] + 0.22 * 8) / (s['iso_n'] + 8.0)))

    def q_3bet(self):
        s = self.st
        return min(1.0, max(0.08, (s['b3_r'] + 0.2 * 8) / (s['b3_n'] + 8.0)))

    # ------------------------------------------------------------- time
    def update_governor(self, hid):
        if self.prev_hid is not None and hid != self.prev_hid and self.prev_left is not None:
            spent = self.prev_left - self.time_left
            if spent >= 0:
                self.ema_ms = spent if self.ema_ms == 0.0 else 0.9 * self.ema_ms + 0.1 * spent
        if hid != self.prev_hid:
            self.prev_hid = hid
            self.prev_left = self.time_left
        hands_left = max(1, self.total_hands - hid + 1)
        avail = self.time_left - 2500.0
        proj = self.ema_ms * hands_left
        if proj > 0.45 * avail and proj > 0:
            self.scale = max(0.10, 0.45 * max(avail, 1.0) / proj)
        else:
            self.scale = 1.0

    def budget_ms(self):
        hands_left = max(1, self.total_hands - self.h.get('id', 1) + 1)
        avail = self.time_left - 2500.0
        per_hand = avail / hands_left
        b = per_hand * 1.6 / 4.5
        cap = 6.0 if self.fast else 40.0
        return max(1.5, min(cap, b) * self.scale)

    def light_equity(self, board):
        """Cheap equity vs a random hand, used when the time bank is nearly gone."""
        rng = self.rng
        my2 = self.h.get('my2')
        if my2 is None:
            if len(board) != 3 or len(self.h.get('hole3', [])) != 3:
                return None
            return max(self.flop_mc(self.h['hole3'], board, [], 3.0, nmax=90, nmin=40))
        dead = set(board) | set(my2) | {self.h['my_disc'], self.h['opp_disc']}
        un = [c for c in range(52) if c not in dead]
        need = 5 - len(board)
        w = 0.0
        n = 100
        for _ in range(n):
            sm = rng.sample(un, 2 + need)
            b = board + sm[2:]
            a = ev(my2 + b)
            c = ev(sm[:2] + b)
            w += 1.0 if a > c else (0.5 if a == c else 0.0)
        return w / n

    def note_bank(self, msg):
        """Read the bank from a request and learn what our replies really cost on this machine."""
        tl = msg.get('time_left_ms', self.time_left)
        try:
            tl = float(tl)
        except (TypeError, ValueError):
            return
        if self.last_tl is not None:
            c = self.last_tl - tl
            if c >= 0.0 and (self.min_rep is None or c < self.min_rep):
                self.min_rep = c
        self.last_tl = tl
        self.time_left = tl
        self.n_rep += 1

    def reserve_ms(self):
        """Bank needed to finish the leg playing only cheap safe replies, with a 2x margin."""
        if self.min_rep is None:
            return 1500.0
        hands_left = max(1, self.total_hands - self.h.get('id', 1) + 1)
        rph = min(8.0, max(3.0, self.n_rep / float(max(1, self.n_hands))))
        return max(1500.0, 2.0 * hands_left * rph * self.min_rep)

    def safe_mode(self):
        return self.time_left < self.reserve_ms()

    def panic(self):
        return self.time_left < max(3500.0, 2.5 * self.reserve_ms())

    # ----------------------------------------------------------- messages
    def handle(self, msg):
        t = msg.get('type')
        if t == 'action_request':
            self.note_bank(msg)
            try:
                return self.on_action(msg)
            except Exception as ex:  # never crash
                elog('action error: %r' % (ex,))
                return self.safe_action(msg)
        if t == 'discard_request':
            self.note_bank(msg)
            try:
                return self.on_discard(msg)
            except Exception as ex:
                elog('discard error: %r' % (ex,))
                return self.safe_discard(msg)
        try:
            if t == 'init':
                self.total_hands = int(msg.get('total_hands', 200))
                self.time_left = float(msg.get('time_bank_ms', 30000))
            elif t == 'new_hand':
                self.n_hands += 1
                self.seat = msg['seat']
                self.h = {'id': msg['hand_id'], 'hole3': [CID[c] for c in msg['hole_cards']],
                          'hist': [], 'range': None, 'my2': None}
            elif t == 'discard_result':
                self.h['my2'] = [CID[c] for c in msg['hole_cards']]
                self.h['my_disc'] = CID[msg['my_discard']]
                self.h['opp_disc'] = CID[msg['opp_discard']]
                self.h['range'] = None
        except Exception as ex:
            elog('state error: %r' % (ex,))
            return None
        if t == 'hand_result':
            try:
                self.on_result(msg)
            except Exception as ex:
                elog('result error: %r' % (ex,))
        elif t == 'match_end':
            self.done = True
        return None

    def safe_action(self, req):
        try:
            legal = req.get('legal_actions') or []
            if 'check' in legal:
                return {'type': 'action', 'action': 'check'}
            if 'call' in legal and req.get('to_call', 99) <= 0.06 * max(1, req.get('pot', 0)):
                return {'type': 'action', 'action': 'call'}
        except Exception:
            pass
        return {'type': 'action', 'action': 'fold'}

    def safe_discard(self, req):
        try:
            cards = req.get('hole_cards')
            if not cards:
                cards = [CSTR[c] for c in self.h.get('hole3', [])]
            if cards:
                worst = min(cards, key=lambda c: RANKS.index(c[0]))
                return {'type': 'discard', 'card': worst}
        except Exception:
            pass
        return {'type': 'discard', 'card': '2s'}

    # ---------------------------------------------------------- results
    def on_result(self, msg):
        hist = msg.get('history', [])
        pre = [e for e in hist if e['street'] == 'preflop']
        s = self.st
        facing = False
        cur_st = None
        first_s = True
        for e in hist:
            if e['street'] != cur_st:
                cur_st = e['street']
                facing = False
                first_s = True
            if e['street'] == 'preflop':
                continue
            if e['actor'] == 'opp':
                s['dec_n'] += 1
                if e['action'] == 'raise':
                    s['dec_agg'] += 1
                if facing:
                    s['f_n'] += 1
                    if e['action'] == 'raise':
                        s['f_r'] += 1
                else:
                    s['o_n'] += 1
                    if e['action'] == 'raise':
                        s['o_b'] += 1
                    ck = (1 if first_s else 2, e['street'])
                    vv = s['oc'].setdefault(ck, [0, 0])
                    vv[0] += 1
                    if e['action'] == 'raise':
                        vv[1] += 1
            if e['action'] == 'raise':
                facing = True
            elif e['action'] == 'call':
                facing = False
            first_s = False
        # opponent reaction to our preflop open-raise (we are the button)
        if self.seat == 'button' and len(pre) > 1 and pre[0]['actor'] == 'me' \
                and pre[0]['action'] == 'raise' and pre[1]['actor'] == 'opp':
            s['ob_n'] += 1
            if pre[1]['action'] == 'fold':
                s['ob_fold'] += 1
        # opponent reaction to our postflop bets
        for i in range(len(hist) - 1):
            e0 = hist[i]
            e1 = hist[i + 1]
            if e0['street'] != 'preflop' and e0['actor'] == 'me' and e0['action'] == 'raise' \
                    and e1['actor'] == 'opp' and e1['street'] == e0['street']:
                s['vb_n'] += 1
                if e1['action'] != 'fold':
                    s['vb_call'] += 1
        if self.seat == 'button' and len(pre) > 1 and pre[0]['actor'] == 'me' \
                and pre[0]['action'] == 'call' and pre[1]['actor'] == 'opp':
            s['iso_n'] += 1
            if pre[1]['action'] == 'raise':
                s['iso_r'] += 1
        if self.seat == 'big_blind':
            if pre:
                s['open_n'] += 1
                if pre[0]['actor'] == 'opp' and pre[0]['action'] == 'raise':
                    s['open_r'] += 1
        else:
            if len(pre) > 1 and pre[0]['actor'] == 'me' and pre[0]['action'] == 'raise' \
                    and pre[1]['actor'] == 'opp':
                s['b3_n'] += 1
                if pre[1]['action'] == 'raise':
                    s['b3_r'] += 1
        if self.SZ_AWARE:
            for ev_ in opp_events(hist, self.seat == 'button'):
                if ev_[1] == 'bet' and ev_[0] != 'preflop':
                    f_ = ev_[3]
                    s['bs'][0 if f_ < 0.4 else (1 if f_ < 0.7 else (2 if f_ < 1.05 else 3))] += 1
        if msg.get('result') == 'showdown' and self.h.get('rc_E') is not None:
            net_ = msg.get('net', 0)
            s['cal_n'] += 1
            s['cal_d'] += (1.0 if net_ > 0 else (0.5 if net_ == 0 else 0.0)) - self.h['rc_E']
        if msg.get('result') == 'showdown' and msg.get('opp_hole_cards') and self.h.get('my2') is not None:
            opp2 = [CID[c] for c in msg['opp_hole_cards']]
            board = [CID[c] for c in msg['board']]
            b3 = board[:3]
            d = CID[msg['opp_discard']]
            vk = flop_value(opp2[0], opp2[1], b3)
            best = max(vk, flop_value(opp2[0], d, b3), flop_value(opp2[1], d, b3))
            pp = disc_probs(opp2[0], opp2[1], d, b3)
            for i in range(3):
                s['pol_ll'][i] += math.log(max(pp[i], 1e-3))
            rg = self.h.get('range')
            if rg is None:
                try:
                    rg = Range(self, self.h['my2'], self.h['my_disc'], self.h['opp_disc'], b3)
                except Exception:
                    rg = None
            if rg is not None:
                seen = set()
                for ev_ in opp_events(hist, self.seat == 'button'):
                    if ev_[1] in ('bet', 'rse') and ev_[0] in ('flop', 'turn', 'river') and ev_[0] not in seen:
                        seen.add(ev_[0])
                        n = {'flop': 3, 'turn': 4, 'river': 5}[ev_[0]]
                        if ev_[0] == 'flop':
                            sc = best
                        else:
                            sc = ev(opp2 + board[:n])
                        p = rg.pct_of(ev_[0], board[:n], sc)
                        s['agg_n'] += 1
                        if p < 0.4:
                            s['agg_weak'] += 1

    # ----------------------------------------------------------- preflop
    def pre_eq(self, hole3):
        key = canon(hole3)
        e = PRE_TABLE.get(key)
        if e is None:
            e = heur_pre(hole3)
        return e

    def raise_to(self, req, amt):
        amt = int(amt)
        lo = req['min_raise']
        hi = req['max_raise']
        amt = max(lo, min(hi, amt))
        return {'type': 'action', 'action': 'raise', 'amount': amt}

    def preflop(self, req):
        legal = req['legal_actions']
        C = req['to_call']
        P = req['pot']
        S = req['my_stack']
        E = self.pre_eq(self.h['hole3'])
        hist = [e for e in req['history'] if e['street'] == 'preflop']
        n_r = sum(1 for e in hist if e['action'] == 'raise')
        if C == 0:
            if 'raise' in legal and E >= self.ISO_T:
                return self.raise_to(req, 8)
            return {'type': 'action', 'action': 'check'}
        if n_r == 0:
            ss = self.steal_s()
            open_thr = 0.545 - 0.145 * ss
            if E >= open_thr and 'raise' in legal:
                if E >= 0.66:
                    return self.raise_to(req, 8)
                return self.raise_to(req, 5 if ss > 0.5 else 6)
            # limp wide in position, but tighten back toward 0.465 against frequent iso-raisers
            lt = self.LIMP_T
            if self.st['iso_n'] >= 6:
                lt += (0.465 - lt) * min(1.0, max(0.0, (self.q_iso() - 0.25) / 0.20))
            if self.LIMP_ON and E >= lt - 0.06 * ss:
                return {'type': 'action', 'action': 'call'}
            return {'type': 'action', 'action': 'fold'}
        L = min(n_r, 3)
        limped = bool(hist) and hist[0]['actor'] == 'me' and hist[0]['action'] == 'call'
        if L == 1 and limped and self.seat == 'button':
            q = self.q_iso()      # a raise of our limp comes from the opponent's iso range, not its open range
        elif L == 1:
            q = self.q_open()
        elif L == 2:
            q = self.q_3bet()
        else:
            q = max(0.05, self.q_3bet() * 0.4)
        R = req['opp_bet']
        if R >= 100:
            q *= 0.5
        elif R >= 30:
            q *= 0.6
        q = max(0.04, q)
        Er = range_eq(q)
        Evs = sigm(logit(E) - logit(Er))
        po = C / float(P + C)
        marg = (0.03 if self.seat == 'button' else 0.05) + 0.07 * min(1.0, C / float(max(S, 1))) * max(0.0, 1.0 - q)
        thr = 0.62 if L == 1 else 0.70
        if 'raise' in legal and L <= 2 and Evs >= thr:
            return self.raise_to(req, R * (3.0 if L == 1 else 2.4))
        if Evs >= po + marg:
            return {'type': 'action', 'action': 'call'}
        if self.ISO_CALL_T and L == 1 and limped and self.seat == 'button' and R <= 10 and E >= self.ISO_CALL_T:
            return {'type': 'action', 'action': 'call'}   # in position, 6 more to win 10+
        return {'type': 'action', 'action': 'fold'}

    # ------------------------------------------------------------ flop MC
    def flop_mc(self, hole3, b3, events, budget_ms, nmax=700, nmin=60):
        rng = self.rng
        dead = set(hole3) | set(b3)
        unseen = [c for c in range(52) if c not in dead]
        opts = ((1, 2), (0, 2), (0, 1))
        myW = [W[hole3[i]] + W[hole3[j]] for i, j in opts]
        myC = [(hole3[i], hole3[j]) for i, j in opts]
        bs3 = W[b3[0]] + W[b3[1]] + W[b3[2]]
        deadline = perf_counter() + budget_ms / 1000.0
        samples = []
        cnt = 0
        while True:
            s = rng.sample(unseen, 5)
            o0, o1, o2 = s[0], s[1], s[2]
            v01 = flop_value(o0, o1, b3)
            v02 = flop_value(o0, o2, b3)
            v12 = flop_value(o1, o2, b3)
            if v01 >= v02 and v01 >= v12:
                best, k1, k2 = v01, o0, o1
            elif v02 >= v12:
                best, k1, k2 = v02, o0, o2
            else:
                best, k1, k2 = v12, o1, o2
            samples.append((best, k1, k2, s[3], s[4]))
            cnt += 1
            if cnt >= nmax or (cnt >= nmin and (cnt & 15) == 0 and perf_counter() > deadline):
                break
        n = len(samples)
        order = sorted(range(n), key=lambda i: samples[i][0])
        pct = [0.0] * n
        for rnk, i in enumerate(order):
            pct[i] = (rnk + 0.5) / n
        evs = []
        for (st_, kind, k, f_, cx) in events:
            if st_ not in ('preflop', 'flop'):
                continue
            if kind == 'bet':
                qv_ = max(0.05, self.q_bet(cx, 'flop') * self.sz_tail(f_))
            elif kind == 'rse':
                qv_ = self.q_rse()
            else:
                qv_ = 0.35
            evs.append((kind, k, self.bluff_q(qv_), qv_))
        eq = [0.0, 0.0, 0.0]
        tw = 0.0
        for i in range(n):
            sv, k1, k2, t, r = samples[i]
            w = 1.0
            for (kind, k, bq_, qv_) in evs:
                w *= self.mult(kind, k, pct[i], bq_, qv_)
            if w < 1e-6:
                continue
            bsum = bs3 + W[t] + W[r]
            board5 = b3 + [t, r]
            to = bsum + W[k1] + W[k2]
            so = ev_sum(to, board5 + [k1, k2])
            tw += w
            for o in range(3):
                tm = bsum + myW[o]
                sm = ev_sum(tm, board5 + list(myC[o]))
                if sm > so:
                    eq[o] += w
                elif sm == so:
                    eq[o] += 0.5 * w
        if tw <= 0:
            return [0.5, 0.5, 0.5]
        return [x / tw for x in eq]

    # ------------------------------------------------------ turn / river
    def get_range(self, b3):
        if self.h.get('range') is None:
            self.h['range'] = Range(self, self.h['my2'], self.h['my_disc'], self.h['opp_disc'], b3)
        return self.h['range']

    def post_equity(self, board, events, budget_ms):
        rg = self.get_range(board[:3])
        n = len(rg.combos)
        bset = set(board)
        w = [(0.0 if (a in bset or c in bset) else x)
             for (a, c), x in zip(rg.combos, rg.wd)]
        b = self.bluff()
        for (street, kind, k, _f, cx) in events:
            if street == 'turn' and len(board) < 4:
                continue
            if street == 'river' and len(board) < 5:
                continue
            bd = {'preflop': board[:3], 'flop': board[:3], 'turn': board[:4], 'river': board[:5]}[street]
            pc = rg.pct(street, bd)
            if kind == 'bet':
                qv = max(0.05, self.q_bet(cx, street) * self.sz_tail(_f))
            else:
                qv = self.q_rse() if kind == 'rse' else 0.35
            bq = self.bluff_q(qv)
            for i in range(n):
                w[i] *= self.mult(kind, k, pc[i], bq, qv)
        my2 = self.h['my2']
        bs = 0
        for c in board:
            bs += W[c]
        myt = bs + W[my2[0]] + W[my2[1]]
        mys = ev_sum(myt, board + my2)
        tw = 0.0
        eq = 0.0
        if len(board) == 5:
            for i in range(n):
                wi = w[i]
                if wi < 1e-7:
                    continue
                a, c2 = rg.combos[i]
                so = ev_sum(bs + W[a] + W[c2], board + [a, c2])
                tw += wi
                if mys > so:
                    eq += wi
                elif mys == so:
                    eq += 0.5 * wi
        else:
            dead = set(board) | set(my2) | {self.h['my_disc'], self.h['opp_disc']}
            rest = [c for c in range(52) if c not in dead]
            nr = len(rest)
            rng = self.rng
            deadline = perf_counter() + budget_ms / 1000.0
            reps = 1
            while True:
                for i in range(n):
                    wi = w[i]
                    if wi < 1e-7:
                        continue
                    a, c2 = rg.combos[i]
                    r = rest[rng.randrange(nr)]
                    while r == a or r == c2:
                        r = rest[rng.randrange(nr)]
                    b5 = board + [r]
                    so = ev_sum(bs + W[r] + W[a] + W[c2], b5 + [a, c2])
                    sm = ev_sum(myt + W[r], b5 + my2)
                    tw += wi
                    if sm > so:
                        eq += wi
                    elif sm == so:
                        eq += 0.5 * wi
                reps += 1
                if reps > max(1, int(self.TURN_REPS * self.scale)) or perf_counter() > deadline:
                    break
        if tw <= 0:
            return 0.5
        return eq / tw

    # ------------------------------------------------------- bet decision
    RAISE_T = (0.82, 0.84, 0.82)
    BET_T = (0.48, 0.49, 0.48)
    FLOP_N = 1200
    DISC_N = 1500
    TURN_REPS = 4
    SLOWPLAY = 2.0
    STAB_ON = 1
    SZ_AWARE = 1
    STAB2 = 2
    STAB_TAB_C = {
        (0, True, 'xx'): (0.55, 0.55, 0.28), (0, True, 'ma'): (0.28, 0.28, 0.10), (0, True, 'oa'): (0.10, 0.10, 0.10),
        (0, False, 'oa'): (0.18, 0.18, 0.0), (0, False, 'xx'): (0.0, 0.05, 0.0), (0, False, 'ma'): (0.10, 0.10, 0.05),
        (1, True, 'ma'): (0.55, 0.55, 0.40), (1, True, 'xx'): (0.28, 0.50, 0.20), (1, True, 'oa'): (0.10, 0.05, 0.0),
        (1, False, 'ma'): (0.18, 0.18, 0.18), (1, False, 'oa'): (0.0, 0.0, 0.0), (1, False, 'xx'): (0.30, 0.45, 0.0),
        (2, True, 'ma'): (0.75, 0.28, 0.0), (2, True, 'xx'): (0.75, 0.35, 0.28), (2, True, 'oa'): (0.28, 0.0, 0.0),
        (2, False, 'ma'): (0.25, 0.18, 0.10), (2, False, 'oa'): (0.0, 0.0, 0.0), (2, False, 'xx'): (0.50, 0.25, 0.0),
    }
    FACE2 = 1
    ISO_CALL_T = 0.0      # off: calling raises of our limp tested worse at full compute
    # per street: extra equity needed to call (small bet on button, small bet in big blind, big bet, raise of our bet)
    FACE_TAB = ((0.04, 0.11, 0.06, 0.22), (0.0, 0.02, 0.02, 0.02), (0.0, 0.0, 0.03, 0.08))
    RCAL_PRIOR = 0.15
    RCAL_N0 = 8.0
    RCAL_SLOPE = 0.5
    RCAL_MAX = 0.10
    # (street, on button, previous-street aggressor) -> stab probability for equity <0.2, 0.2-0.4, >=0.4
    STAB_TAB = {
        (0, True, 'xx'): (0.60, 0.60, 0.30), (0, True, 'ma'): (0.28, 0.28, 0.10), (0, True, 'oa'): (0.10, 0.10, 0.10),
        (0, False, 'oa'): (0.50, 0.18, 0.0), (0, False, 'xx'): (0.0, 0.05, 0.0), (0, False, 'ma'): (0.10, 0.10, 0.05),
        (1, True, 'ma'): (0.65, 0.65, 0.55), (1, True, 'xx'): (0.28, 0.60, 0.20), (1, True, 'oa'): (0.10, 0.05, 0.0),
        (1, False, 'ma'): (0.18, 0.30, 0.18), (1, False, 'oa'): (0.0, 0.0, 0.0), (1, False, 'xx'): (0.40, 0.60, 0.0),
        (2, True, 'ma'): (0.85, 0.30, 0.0), (2, True, 'xx'): (0.85, 0.40, 0.40), (2, True, 'oa'): (0.30, 0.0, 0.20),
        (2, False, 'ma'): (0.55, 0.45, 0.18), (2, False, 'oa'): (0.15, 0.0, 0.0), (2, False, 'xx'): (0.80, 0.40, 0.0),
    }
    SZ_PRIOR = (1.2, 1.6, 0.8, 0.4)
    CALIB = 0.0
    CAL_PRIOR = -0.10
    CAL_N0 = 10.0
    CAL_W = (0.3, 0.6, 1.0)
    LIMP_T = 0.33
    ISO_T = 0.51
    FACE_ADD = (0.03, 0.06, 0.10)
    STAB_BTN = 0.28
    STAB_BB = 0.18
    STAB_SZ = 0.55
    STAB_CR = 0.65
    CTX_Q = 1
    EVT_MILD = 1
    PRE_EVT = 1
    LIMP_ON = 1
    CR_DROP = 0.08
    MARGIN0 = 0.0
    MARGIN1 = 0.03

    def prev_agg(self, req, street):
        """Who made the last raise on the previous street: 'ma' me, 'oa' opponent, 'xx' nobody."""
        prev = {'flop': 'preflop', 'turn': 'flop', 'river': 'turn'}.get(street)
        last = None
        for e in req['history']:
            if e['street'] == prev and e['action'] == 'raise':
                last = e['actor']
        return 'ma' if last == 'me' else ('oa' if last == 'opp' else 'xx')

    def reraised(self, req):
        mine = False
        for e in req['history']:
            if e['street'] != req['street']:
                continue
            if e['actor'] == 'me' and e['action'] == 'raise':
                mine = True
            elif mine and e['actor'] == 'opp' and e['action'] == 'raise':
                return True
        return False

    def checked_this_street(self, req):
        for e in req['history']:
            if e['street'] == req['street'] and e['actor'] == 'me' and e['action'] == 'check':
                return True
        return False

    def first_to_act(self, req):
        if req['my_bet'] != 0 or req['opp_bet'] != 0:
            return False
        for e in req['history']:
            if e['street'] == req['street']:
                return False
        return True

    def trap_prob(self, req, E, street):
        """Probability of slow-playing a very strong hand when we act first."""
        if self.SLOWPLAY <= 0 or not self.first_to_act(req):
            return 0.0
        q = self.q_bet(2, street)
        if q < 0.35:
            return 0.0
        if street == 'river' and (q < 0.55 or E < 0.92):
            return 0.0
        if E < 0.80:
            return 0.0
        return self.SLOWPLAY * min(0.40, (q - 0.30) * 1.6)

    def bet_decision(self, req, E, street):
        legal = req['legal_actions']
        C = req['to_call']
        P = req['pot']
        S = req['my_stack']
        si = {'flop': 0, 'turn': 1, 'river': 2}.get(street, 0)
        if C > 0:
            po = C / float(P + C)
            margin = self.MARGIN0 + self.MARGIN1 * min(1.0, C / float(max(S, 1)))
            fr_ = C / float(max(1, P - C))
            mine_ = self.bet_this_street(req)
            if self.FACE2:
                ft = self.FACE_TAB[si]
                if mine_:
                    margin += ft[3]
                elif fr_ >= 0.7:
                    margin += ft[2]
                else:
                    margin += ft[0 if self.seat == 'button' else 1]
                    if si == 2:
                        margin += self.river_adj()
            else:
                margin += self.face_add(si)   # our equity vs a betting range runs optimistic
            rt = self.RAISE_T[si]
            if self.CR_DROP > 0 and self.checked_this_street(req) and self.q_bet(2, street) >= 0.45:
                rt -= self.CR_DROP
            if 'raise' in legal and E >= rt and not self.reraised(req):
                amt = req['opp_bet'] + 0.75 * (P + C)
                if req['max_raise'] - amt < 0.35 * (P + C):
                    amt = req['max_raise']
                return self.raise_to(req, amt)
            if E >= po + margin:
                if street == 'river' and (not self.FACE2 or (fr_ < 0.7 and not mine_)):
                    self.h['rc_E'] = E
                return {'type': 'action', 'action': 'call'}
            return {'type': 'action', 'action': 'fold'}
        if 'raise' in legal and self.trap_prob(req, E, street) > self.rng.random():
            return {'type': 'action', 'action': 'check'}
        if 'raise' in legal:
            f = 0.0
            cr = self.call_rate()
            bt = self.BET_T[si] - (0.03 if cr > 0.72 else 0.0)
            if E >= 0.90:
                f = 0.80
            elif E >= 0.80:
                f = 0.65
            elif E >= 0.70:
                f = 0.50
            elif E >= bt:
                f = 0.33
            if f > 0:
                f *= 1.3 if cr > 0.72 else (0.85 if cr < 0.4 else 1.0)
                amt = max(req['min_raise'], f * P)
                if req['max_raise'] - amt < 0.3 * P:
                    amt = req['max_raise']
                return self.raise_to(req, amt)
            if self.STAB_ON and cr <= self.STAB_CR:
                fq = self.STAB_BTN if self.seat == 'button' else self.STAB_BB
                if self.STAB2:
                    t3 = (self.STAB_TAB if self.STAB2 == 1 else self.STAB_TAB_C).get((si, self.seat == 'button', self.prev_agg(req, street)))
                    if t3 is not None:
                        fq = t3[0 if E < 0.2 else (1 if E < 0.4 else 2)]
                if self.rng.random() < fq:
                    return self.raise_to(req, max(req['min_raise'], self.STAB_SZ * P))
        return {'type': 'action', 'action': 'check'}

    # ------------------------------------------------------------ actions
    def on_action(self, req):
        street = req['street']
        self.h['hist'] = req['history']
        self.update_governor(req.get('hand_id', self.h.get('id', 1)))
        if street == 'preflop':
            return self.preflop(req)
        if self.safe_mode():
            return self.safe_action(req)
        board = [CID[c] for c in req['board']]
        if self.panic():
            E = self.light_equity(board)
            if E is None:
                return self.safe_action(req)
            return self.bet_decision(req, E, street)
        events = opp_events(req['history'], self.seat == 'button')
        bud = self.budget_ms()
        if street == 'flop':
            eqs = self.flop_mc(self.h['hole3'], board[:3], events, bud, nmax=max(80, int(self.FLOP_N * self.scale)))
            E = max(eqs)
        else:
            if self.h.get('my2') is None:
                return self.safe_action(req)
            E = self.post_equity(board, events, bud)
        return self.bet_decision(req, E, street)

    def on_discard(self, req):
        hole = [CID[c] for c in req['hole_cards']]
        b3 = [CID[c] for c in req['board']]
        self.h['hole3'] = hole
        if self.safe_mode():
            return self.safe_discard(req)
        if self.panic():
            eqs = self.flop_mc(hole, b3, [], 3.0, nmax=120, nmin=40)
            bi = max(range(3), key=lambda i: (round(eqs[i], 4), -(hole[i] >> 2)))
            return {'type': 'discard', 'card': CSTR[hole[bi]]}
        events = opp_events(self.h.get('hist', []), self.seat == 'button')
        eqs = self.flop_mc(hole, b3, events, self.budget_ms() * 1.3, nmax=max(100, int(self.DISC_N * self.scale)), nmin=min(100, max(40, int(100 * self.scale))))
        bi = max(range(3), key=lambda i: (round(eqs[i], 4), -(hole[i] >> 2)))
        return {'type': 'discard', 'card': CSTR[hole[bi]]}


def main():
    ag = Agent()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except ValueError:
            continue
        if not isinstance(msg, dict):
            continue
        t = msg.get('type')
        reply = None
        try:
            reply = ag.handle(msg)
        except Exception as ex:
            elog('fatal handle error: %r' % (ex,))
            reply = None
        if reply is None:
            # a request must always get exactly one reply
            try:
                if t == 'action_request':
                    reply = ag.safe_action(msg)
                elif t == 'discard_request':
                    reply = ag.safe_discard(msg)
            except Exception:
                reply = None
        if reply is not None:
            try:
                out.write(json.dumps(reply) + '\n')
                out.flush()
            except Exception:
                break
        if ag.done:
            break


if __name__ == '__main__':
    main()
